import { mc, pt, ref } from './helpers.js'

export const STAGE3 = [
{
  id: 'scaling', title: 'Scaling: vertical, horizontal, stateless', stage: 3, tier: 'must', minutes: 45, prereq: ['why-slow', 'login-flow'], related: ['load-balancing'],
  hook: { story: 'You built a website. 100 people use it. Suddenly 100,000 do. All requests go to one server.', ask: 'What are your options? Which one has a ceiling, and which one has a catch?', hints: ['You can make the machine bigger.', 'You can add more machines.', 'If a user\'s data sits in one machine\'s memory, what happens when their next request lands on another?'], reveal: 'Bigger machine (vertical): simple, but there is a ceiling and a single point of failure. More machines (horizontal): nearly unlimited and resilient, but only works smoothly if any machine can serve any request, i.e. servers are stateless.' },
  levels: [
    { title: 'Understand', body: ['**Vertical scaling (scale up):** buy a bigger machine: more CPU, RAM. Like replacing a small van with a bigger truck. Easy, but trucks only get so big and cost rises steeply.', '**Horizontal scaling (scale out):** add more machines and share the work. Like adding more vans. No real ceiling, and if one breaks the others keep going.', 'To scale out cleanly, any server must be able to handle any request. That means servers must not keep your personal data in their own memory: they should be **stateless**.'],
      check: mc('Which scaling method adds more machines?', ['Vertical', 'Horizontal', 'Diagonal', 'Lateral caching'], 1, 'Horizontal = scale out.') },
    { title: 'Explore', body: ['**Stateless server:** each request carries (or can look up) everything needed; the server keeps nothing between requests. State (sessions, files, data) lives in shared systems: database, Redis, object storage.', '**Stateful server:** remembers per-client info locally (in-memory sessions, local file uploads, WebSocket connections). Harder to scale because requests must return to the same machine (sticky sessions) and a crash loses state.'],
      steps: ['Move sessions to Redis or tokens.', 'Move uploaded files to object storage (S3), not local disk.', 'Keep config in environment variables so every instance is identical.', 'Put a load balancer in front (next lesson). Now instances are interchangeable, like cattle not pets.'],
      check: mc('Which change makes an app server more stateless?', ['Keep sessions in local memory', 'Store sessions in shared Redis', 'Store uploads on local disk', 'Use sticky sessions'], 1, 'Shared state lets any server serve any request.') },
    { title: 'Apply', body: ['**Scenario: your app works on one server but fails when run on three.** Symptoms: users logged out randomly, uploaded images missing, scheduled job runs three times. Causes: in-memory sessions, local-disk uploads, and a cron job running on every instance. Each is hidden state or hidden duplication. Fix by externalising state and designating one place for scheduled work (a job queue/leader).', 'Also ask: which layer scales this way? App servers scale out easily. **Databases are stateful by nature**, so they need replication and sharding, which is harder, and why most designs push as much load as possible away from the database.'],
      check: mc('Uploaded images exist only on server 1\'s disk. User hits server 2. Result and fix?', ['Image shown; nothing', 'Image missing; use shared object storage', 'Faster; ignore', 'DNS failure'], 1, 'Local disk is state.') },
    { title: 'Master', body: ['Scale-up first is often the right answer: a single 64-core database server handles a surprising load and avoids distributed complexity. Move to scale-out when you need more than one machine can give, or need redundancy. Autoscaling adds/removes instances on metrics (CPU, queue depth, request rate) but has lag, so you need warm capacity for sudden spikes, and the database must be able to absorb the extra instances\' connections.', 'Amdahl\'s law reminder: the part of the system that cannot be parallelised (a single database, a global lock, a single queue partition) caps the benefit of adding servers.'],
      check: mc('Why does adding servers sometimes not improve throughput?', ['Servers are lazy', 'A shared non-parallel component (e.g. one database) is the bottleneck', 'DNS', 'CSS'], 1, 'The serial portion limits speedup.') },
  ],
  diagram: { caption: 'Scale out behind a balancer', rows: [['Users'], ['Load balancer'], ['App 1', 'App 2', 'App 3'], ['Shared DB / Redis']], link: 'fan' },
  sections: { when: ['Vertical for quick wins and databases early on; horizontal for stateless tiers and resilience.'], whenNot: ['Do not scale out a stateful tier before externalising its state.'], tradeoffs: ['Simplicity (vertical) vs resilience and ceiling (horizontal).'], real: ['Stateless web tiers on autoscaling groups (AWS ASG, Kubernetes HPA).'] },
  connects: 'Statelessness (from the login lesson) is the key that makes this possible, and a load balancer is how traffic is spread across the identical servers.',
  quiz: [
    mc('What is a downside of vertical scaling?', ['Needs many machines', 'Has a ceiling and is a single point of failure', 'Needs load balancers', 'Cannot run code'], 1, 'One machine, finite size.'),
    mc('What makes a server stateless?', ['No CPU', 'It keeps no per-client data between requests', 'No network', 'No code'], 1, 'State lives elsewhere.'),
    mc('Where should user-uploaded files go in a scaled-out app?', ['Each server\'s disk', 'Shared object storage', 'The browser', 'RAM'], 1, 'Shared and durable.'),
    mc('A cron job emails everyone daily; after scaling to 4 instances users get 4 emails. Fix?', ['Ignore', 'Run scheduled jobs from one place (a queue/leader/scheduler)', 'Add 4 more servers', 'Disable email'], 1, 'Avoid duplicating singleton work.', 'scenario'),
    mc('Traffic is 3x for 10 minutes every hour. Autoscaling takes 5 minutes to add servers. Sensible approach?', ['Hope', 'Scheduled/predictive scaling or warm headroom plus queues to absorb the burst', 'Vertical only', 'Disable autoscaling'], 1, 'Lag means plan for it.', 'scenario'),
  ],
  interview: { q: 'Vertical vs horizontal scaling: what are the trade-offs and what must change in your app to scale horizontally?', model: 'Vertical: simple, no code changes, but hardware ceiling, rising cost and a single point of failure. Horizontal: near-linear capacity and redundancy, but requires stateless services, load balancing, shared session/cache/storage, externalised config, and handling of data consistency. Databases are harder to scale out (replication, sharding). Often scale up first, then out where needed.', points: [pt('Vertical: simple but ceiling/SPOF', 'ceiling', 'limit', 'single point'), pt('Horizontal: scale + redundancy', 'redundan', 'availab', 'more machines'), pt('Stateless requirement', 'stateless'), pt('Shared session/storage and load balancer', 'redis', 'shared', 'load balancer'), pt('Database is the hard part', 'database', 'shard', 'replica')] },
  challenge: { q: 'Take a single-server photo app (local disk uploads, in-memory sessions, nightly thumbnail cron) and list exactly what you change so it can run on 5 instances.', hints: ['Find every piece of local state.', 'What runs "once" but would now run five times?'], model: 'Sessions to Redis (or signed tokens); uploads to object storage with CDN; thumbnails generated by a background worker from a queue; the nightly job moved to a scheduler/leader; config via env vars; load balancer with health checks in front.', points: [pt('Sessions externalised', 'redis', 'session', 'token'), pt('Uploads to object storage', 's3', 'object storage'), pt('Singleton jobs handled once', 'queue', 'scheduler', 'leader', 'worker'), pt('Load balancer + health checks', 'load balancer', 'health')] },
  summary: { key: ['Scale up = bigger; scale out = more.', 'Stateless servers make scale-out easy.', 'Databases are the hard-to-scale state.'], mistakes: ['Sticky sessions as a long-term fix.', 'Scaling app servers when the DB is the limit.'], remember: 'Move state out of servers so servers become interchangeable.' },
  refs: [ref('The Twelve-Factor App', 'https://12factor.net/', 'Principles for stateless, scalable services (processes, config, backing services).'), ref('AWS: Scaling in the cloud', 'https://aws.amazon.com/architecture/', 'Reference architectures showing scale-out patterns.')],
},
{
  id: 'load-balancing', title: 'Load balancers and reverse proxies', stage: 3, tier: 'must', minutes: 55, prereq: ['scaling', 'ip-dns'], related: ['rate-limiting', 'cdn'],
  hook: { story: 'You now have 5 identical servers. Your domain can only point somewhere. Users type one address.', ask: 'Who decides which server handles each request? What should happen when server 3 dies? What if server 2 is slower than the rest?', hints: ['Something must sit in front and receive every request.', 'How does it know which servers are alive?', 'Is "take turns" always the fairest way?'], reveal: 'A **load balancer** receives every request and forwards it to a healthy server chosen by an algorithm. It checks server health, stops sending traffic to dead ones, and is itself made redundant so it is not a new single point of failure.' },
  levels: [
    { title: 'Understand', body: ['A load balancer is a traffic officer at a roundabout: cars (requests) arrive on one road and it sends each down one of several exits (servers), avoiding blocked ones.', 'Benefits: **capacity** (spread work), **availability** (a dead server is skipped), **flexibility** (add or remove servers without users noticing).', 'A **reverse proxy** is a server that sits in front of your servers on behalf of them (Nginx, HAProxy). A load balancer is a reverse proxy that spreads requests across several backends. It can also terminate HTTPS, compress and cache.'],
      check: mc('What happens to traffic when one backend server dies?', ['All traffic fails', 'The load balancer stops sending to it after health checks fail', 'Users must retry', 'DNS updates instantly'], 1, 'Health checks remove it from rotation.') },
    { title: 'Explore', body: ['**Algorithms:**'],
      steps: ['**Round robin:** take turns. Simple, assumes equal servers and equal request cost.', '**Weighted round robin:** bigger servers get proportionally more.', '**Least connections:** send to the server with fewest active requests. Good when request durations vary.', '**IP / consistent hash:** same client or key always goes to the same server (sticky), useful for caches and WebSockets.', '**Random with two choices:** pick two at random, choose the less loaded; surprisingly effective at scale.'],
      body2: ['**Layer 4** balancers route by IP/port (fast, simple, protocol-agnostic). **Layer 7** balancers understand HTTP: route by path (`/api` vs `/static`), host header, cookies; can do TLS termination and retries. **Health checks:** active (probe `/health` every few seconds) and passive (watch real errors). Use the simulator in Labs to feel these differences.'],
      check: mc('Request durations vary from 10 ms to 10 s. Best algorithm?', ['Round robin', 'Least connections', 'Fixed server', 'Random single'], 1, 'Round robin ignores that some servers are busy with slow requests.') },
    { title: 'Apply', body: ['**Scenario: 100 users become 100,000.** Add 10 app servers behind a load balancer; set a health check; keep sessions in Redis. Now what if one server gets a poisoned request and crashes repeatedly? Health checks eject it. What if the load balancer itself dies? Run two (active-passive with a floating IP, or active-active behind DNS / anycast / the cloud provider\'s managed balancer).', 'Think about **connection draining**: during deploys, stop sending new requests to a server but let in-flight ones finish, for zero-downtime releases.'],
      check: mc('How do you deploy a new version with no dropped requests?', ['Turn everything off', 'Drain a server (finish in-flight), update, health-check, return to rotation, repeat', 'Ask users to wait', 'Change DNS only'], 1, 'Rolling deploys with draining.') },
    { title: 'Master', body: ['The balancer can become the bottleneck or SPOF, so it is scaled and replicated; at global scale, **DNS/anycast geo-routing** sends users to the nearest region, then a regional balancer distributes inside it. Failure modes: **thundering herd** after recovery (slow-start new servers so they are not overwhelmed), **uneven load** from sticky sessions or hot keys, and **retries amplifying** an overload (limit retries at the balancer). Observe per-backend latency and error rates, and use **outlier detection** to eject slow-but-alive servers.'],
      check: mc('What stops a newly started server from being crushed by a flood of traffic?', ['Nothing', 'Slow-start ramping its weight up gradually', 'More DNS', 'Lower TTL'], 1, 'Warm caches and JITs need time.') },
  ],
  diagram: { caption: 'Load balancer with health checks', rows: [['Clients'], ['Load balancer'], ['Server A', 'Server B', 'Server C (down)']], link: 'fan' },
  sections: { when: ['Any time more than one server handles the same traffic; also useful with one server for TLS and routing.'], whenNot: ['Not needed for a single small server; do not forget to make the balancer itself redundant.'], tradeoffs: ['Extra hop and component to run vs capacity and availability.'], real: ['AWS ALB/NLB, Google Cloud Load Balancing, Nginx, HAProxy, Envoy.'] },
  connects: 'This only works because servers are stateless (previous lesson). It also sets up rate limiting and API gateways, which are specialised proxies in the same position.',
  quiz: [
    mc('Which algorithm assumes equal servers and equal requests?', ['Least connections', 'Round robin', 'Weighted', 'Hash'], 1, 'Plain round robin.'),
    mc('A layer 7 balancer can route by…?', ['Only IP', 'URL path or host', 'Only port', 'Nothing'], 1, 'It understands HTTP.'),
    mc('What do health checks do?', ['Encrypt', 'Detect failing servers so traffic avoids them', 'Cache', 'Index'], 1, 'Remove bad backends from rotation.'),
    mc('Your single load balancer machine fails and the whole site is down. Lesson?', ['Use more databases', 'The balancer is a single point of failure; make it redundant', 'Remove it', 'Use UDP'], 1, 'Redundancy at every tier.', 'scenario'),
    mc('A WebSocket app needs each user\'s connection kept on the same backend across reconnects. Option?', ['Random', 'Hash on user id (sticky)', 'Round robin', 'Disable'], 1, 'Consistent routing by key.', 'scenario'),
  ],
  interview: { q: 'How does a load balancer work, and how do you avoid it becoming a single point of failure?', model: 'It receives client requests and forwards each to a healthy backend selected by an algorithm (round robin, least connections, hash). It runs health checks, drains servers on deploys, may terminate TLS and route at layer 4 or 7. To avoid being a SPOF, run it redundantly: active-passive pair with a virtual IP and failover, active-active behind DNS/anycast, or use a managed cloud load balancer; at global scale use geo DNS in front of regional balancers.', points: [pt('Distributes requests across backends via an algorithm', 'round robin', 'least connection', 'algorithm'), pt('Health checks / removal of bad servers', 'health'), pt('Layer 4 vs 7 / TLS termination', 'layer', 'tls', 'ssl'), pt('Redundant balancers (active-passive/active)', 'redundan', 'active', 'failover', 'virtual ip', 'managed'), pt('Statelessness / sessions', 'stateless', 'sticky', 'session')] },
  challenge: { q: 'Design the traffic path for a site serving users in India and Europe from two regions, surviving the loss of one server, one balancer, and one region.', hints: ['What decides which region a user reaches?', 'What detects each kind of failure?'], model: 'Geo/latency DNS (or anycast) picks the nearest region; each region has two or more balancers (managed or active-passive) over several servers in different availability zones, with health checks at each layer. If a region fails, DNS health checks shift traffic to the other region (after TTL); data must be replicated across regions for that to work.', points: [pt('Geo/latency DNS to choose region', 'geo', 'dns', 'anycast', 'latency'), pt('Multiple balancers / AZs', 'multiple', 'zone', 'redundan', 'two'), pt('Health checks at each layer', 'health'), pt('Cross-region data replication needed', 'replicat', 'data')] },
  summary: { key: ['Balancer spreads requests and hides dead servers.', 'Algorithms: round robin, least connections, hash.', 'Make the balancer redundant.'], mistakes: ['Round robin with uneven request cost.', 'Forgetting draining and slow start.'], remember: 'Stateless servers + balancer = horizontal scaling.' },
  refs: [ref('Cloudflare: What is load balancing?', 'https://www.cloudflare.com/learning/performance/what-is-load-balancing/', 'Concise overview of algorithms and health checks.'), ref('Nginx docs: HTTP load balancing', 'https://nginx.org/en/docs/http/load_balancing.html', 'Official reference showing real configuration of the algorithms.')],
},
{
  id: 'caching', title: 'Caching and Redis', stage: 3, tier: 'must', minutes: 60, prereq: ['indexing', 'why-slow'], related: ['cdn', 'replication-sharding'],
  hook: { story: 'Imagine 10 lakh people open the same celebrity\'s Instagram profile in the same minute. Every time, the app fetches the same name, photo and follower count from the database.', ask: 'What problems occur? If the answer is the same every time, do we need to ask the database every time?', hints: ['What happens to the database as requests multiply?', 'Where could a recently fetched answer be kept so it is faster to reach?', 'What could go wrong if the stored copy becomes outdated?'], reveal: 'The database becomes the bottleneck and everything slows. A **cache** keeps recent answers in fast memory close to the app, so most requests never touch the database. The price: the copy can become stale and must be managed.' },
  levels: [
    { title: 'Understand', body: ['A **cache** is a small, very fast storage that keeps copies of frequently needed data. Like keeping your most-used books on your desk instead of walking to the library each time.', 'A **cache hit** means the answer was found (fast). A **cache miss** means it was not, so you fetch from the slow source (database) and keep a copy for next time.', '**Redis** is a popular in-memory data store used as a cache: reading from RAM takes microseconds, a database query takes milliseconds.'],
      check: mc('What is a cache miss?', ['Data found in the cache', 'Data not in the cache, so it must be fetched from the source', 'A crashed server', 'A deleted database'], 1, 'The slow path.') },
    { title: 'Explore', body: ['Common pattern: **cache-aside** (lazy loading):'], code: { lang: 'python', text: 'def get_profile(user_id):\n    key = f"profile:{user_id}"\n    data = redis.get(key)\n    if data:                       # hit\n        return json.loads(data)\n    row = db.query("SELECT ... WHERE id=%s", user_id)   # miss\n    redis.setex(key, 300, json.dumps(row))              # keep 5 minutes (TTL)\n    return row' },
      steps: ['**Eviction:** memory is limited, so when full the cache removes entries: **LRU** (least recently used), LFU (least frequently used), FIFO.', '**TTL:** every entry expires after a time, bounding staleness.', '**Invalidation:** when data changes, delete or update the cached copy ("there are only two hard things in computer science…").', '**Write strategies:** cache-aside, write-through (write cache and DB together), write-back (write cache first, DB later: fast but risky).', '**Hit ratio** = hits / (hits + misses). At 95% hit ratio only 5% of traffic reaches the database: a 20x reduction.'],
      check: mc('Which eviction policy removes the entry that has not been used for the longest time?', ['FIFO', 'LRU', 'Random', 'TTL'], 1, 'Least Recently Used.') },
    { title: 'Apply', body: ['**Scenario: your cache contains outdated information.** A user changes their profile photo but others still see the old one for 5 minutes. Options: shorter TTL, delete the cached key when the profile is updated (**invalidate on write**), or version keys (`profile:42:v7`). Pick based on how much staleness the product tolerates: a like-count can be 30 seconds stale; an account balance cannot be.', 'Also design for the **cache stampede**: a hot key expires and 10,000 requests miss simultaneously, hammering the database. Defences: request coalescing (one loader, others wait), jittered TTLs, refreshing before expiry.'],
      check: mc('A hot key expires and the database is flooded by simultaneous misses. Name and a fix?', ['Deadlock; remove locks', 'Cache stampede; coalesce loads / jitter TTL / refresh early', 'N+1; join', 'DNS flap; change TTL'], 1, 'Protect the source from synchronized misses.') },
    { title: 'Master', body: ['Caches exist at many layers: browser, CDN, reverse proxy, application (Redis/Memcached), database buffer pool. Cache what is **read-heavy, expensive to compute and tolerant of staleness**. Distributed caches shard keys across nodes using **consistent hashing** so that adding a node moves few keys. Pitfalls: caching errors/empties (**negative caching** with a short TTL is deliberate; accidental is a bug), **hot keys** overwhelming one node (replicate or split the key), cold start after a restart (warm up), and cache as a hidden dependency (if Redis dies, can the database survive the sudden full load? Often not: design a fallback or rate limit).', 'Facebook\'s Memcache paper and Twitter\'s timeline caches are the classic real-world case studies.'],
      check: mc('Redis restarts and all keys vanish. The database melts. Mitigation?', ['Remove caching', 'Warm the cache gradually, rate limit/shed load, use replicas/persistence', 'Lower TTL', 'Use UDP'], 1, 'Plan for cold starts.') },
  ],
  diagram: { caption: 'Cache-aside', rows: [['App'], ['Redis cache (fast)'], ['Database (slow)']], link: 'chain' },
  sections: { when: ['Read-heavy, repeated, expensive reads where slightly stale data is acceptable.'], whenNot: ['Write-heavy data, data that must always be fresh (balances), or low-hit-ratio workloads where it only adds complexity.'], tradeoffs: ['Speed and reduced DB load vs staleness, invalidation complexity and another failure point.'], real: ['Instagram/Facebook use Memcache/Redis at enormous scale; Twitter caches timelines; Stack Overflow serves most pages from cache.'] },
  connects: 'Indexing made a query fast; caching avoids running it. Cache nodes are also scaled with consistent hashing, a sharding idea you will meet again.',
  quiz: [
    mc('Cache hit ratio is 90%. What fraction of reads reach the database?', ['90%', '10%', '0%', '100%'], 1, 'Only misses go through.'),
    mc('What is cache-aside?', ['DB pushes to cache', 'App checks cache, on miss loads from DB and stores it', 'Cache replaces DB', 'Cache writes to disk only'], 1, 'The application manages the cache.'),
    mc('Why set a TTL?', ['Compression', 'Bound staleness and memory use', 'Encryption', 'Routing'], 1, 'Entries expire eventually.'),
    mc('Product prices change rarely but must never show wrong at checkout. Strategy?', ['Cache forever', 'Cache for browsing with short TTL/invalidation; read authoritative price at checkout', 'No caching ever', 'Random TTL'], 1, 'Tolerance differs per use.', 'scenario'),
    mc('Your cache has a 20% hit ratio and costs more than it saves. What do you reconsider?', ['Add servers', 'What you cache: key choice, TTL, size, or whether to cache at all', 'Use bigger fonts', 'Rewrite DNS'], 1, 'Low hit ratio = poor fit.', 'scenario'),
  ],
  interview: { q: 'How would you add caching to reduce load on a read-heavy database? What are the pitfalls?', model: 'Identify hot, read-heavy, stale-tolerant data and use cache-aside with Redis: check the cache, on miss load from the DB and store with a TTL. Choose eviction (LRU) and size for a high hit ratio. Handle invalidation on writes (delete key or short TTL), stampedes (coalescing, jitter), hot keys, cold starts and Redis failure (graceful fallback). Trade-offs: staleness, extra infrastructure, consistency complexity. Use CDN/browser caching for static or public content.', points: [pt('Cache-aside with Redis/Memcached', 'cache-aside', 'redis', 'memcache'), pt('TTL and eviction (LRU)', 'ttl', 'lru', 'evict'), pt('Invalidation / staleness', 'invalidat', 'stale'), pt('Stampede / hot key / cold start', 'stampede', 'hot key', 'cold', 'thundering'), pt('Hit ratio and trade-offs', 'hit ratio', 'trade')] },
  challenge: { q: 'A user profile page is read 1,000x more than it is written. Design the caching: keys, TTL, invalidation, and what you do when the user updates their name.', hints: ['What is the key? Who needs fresh data right after an update?', 'Delete vs update on write?'], model: 'Key profile:{id}; value JSON; TTL ~5-15 min with jitter. On update: write DB, then delete the key (next read repopulates). The author can be shown their own fresh data by reading through to the DB right after their update. Protect against stampede for celebrity profiles with request coalescing.', points: [pt('Sensible key and TTL', 'profile:', 'key', 'ttl'), pt('Invalidate on write (delete key)', 'delete', 'invalidat'), pt('Read-your-own-write consideration', 'own', 'author', 'fresh'), pt('Stampede/hot key protection', 'stampede', 'coalesc', 'hot')] },
  summary: { key: ['Cache = fast copy of hot data.', 'Hit vs miss, TTL, eviction (LRU), invalidation.', 'Trade freshness for speed and DB relief.'], mistakes: ['Caching everything.', 'No plan for invalidation or cold start.'], remember: 'Caching reduces database load; it does not make the database correct.' },
  refs: [ref('Redis docs: Client-side caching and patterns', 'https://redis.io/docs/latest/develop/', 'Official Redis docs; learn the concepts, not every command.'), ref('Scaling Memcache at Facebook (paper)', 'https://www.usenix.org/conference/nsdi13/technical-sessions/presentation/nishtala', 'Classic real-world cache-at-scale case study.'), ref('Cloudflare: What is caching?', 'https://www.cloudflare.com/learning/cdn/what-is-caching/', 'Beginner-friendly overview.')],
},
{
  id: 'cdn', title: 'CDNs and static content', stage: 3, tier: 'should', minutes: 35, prereq: ['caching', 'ip-dns'], related: ['load-balancing'],
  hook: { story: 'Your servers are in Mumbai. A user in Brazil loads your 3 MB homepage. Every image makes the long trip across the ocean.', ask: 'The images are identical for every user. Why should each one travel 15,000 km from your server?', hints: ['Where could a copy be kept closer to the user?', 'Who would own and update those copies?', 'What kind of content is safe to copy?'], reveal: 'Put copies of unchanging content on servers around the world (a **CDN**) so users download from nearby. Your origin serves only cache misses.' },
  levels: [
    { title: 'Understand', body: ['A **Content Delivery Network** is a worldwide network of cache servers (**edge** locations). The first user in São Paulo triggers a fetch from your origin; the next thousand get it from the nearby edge.', 'Best for **static** files: images, videos, CSS, JavaScript, downloads. Also protects your origin from traffic spikes and some attacks.'],
      check: mc('What does a CDN primarily reduce?', ['Database size', 'Distance (latency) and origin load for static content', 'Password hashing', 'SQL joins'], 1, 'Serve from nearby copies.') },
    { title: 'Explore', body: ['Flow: browser requests `cdn.example.com/logo.png` → DNS/anycast directs to the nearest edge → edge has it? serve (hit) : fetch from origin, store, serve (miss). Control with HTTP headers: `Cache-Control: public, max-age=31536000, immutable`.'],
      steps: ['**Pull CDN:** edge fetches from origin on demand. Simplest.', '**Push CDN:** you upload content to the CDN ahead of time.', '**Cache busting:** filename includes a content hash (`app.4f9a2c.js`) so a new version is a new URL and old caches never matter.', '**Purge/invalidate:** explicit removal when you cannot change URLs.', 'CDNs can also cache API responses, terminate TLS near users, and run code at the edge.'],
      check: mc('How do you ship a new version of app.js through a CDN with a one-year cache?', ['Wait a year', 'Change the filename (content hash) so it is a new URL', 'Turn off the CDN', 'Lower TTL to 1s'], 1, 'Versioned URLs make long caching safe.') },
    { title: 'Apply', body: ['**Scenario: a video goes viral and your origin bandwidth bill and latency explode.** Put the video behind a CDN; large files are split into segments (HLS/DASH) so edges cache pieces; origin shielding adds a middle cache tier so the origin sees one request per object, not one per edge.', 'Decide what is cacheable: public, identical for all users (yes). Personalised pages with cookies (careful: never cache one user\'s private page and serve it to others).'],
      check: mc('Which must NOT be cached publicly at the edge?', ['Logo', 'A page showing a logged-in user\'s account details', 'CSS', 'Public images'], 1, 'Private, per-user data needs private/no-store.') },
    { title: 'Master', body: ['Trade-offs: cost per GB, purge delays (seconds to minutes), cache-key design (query strings, headers like `Vary`), and consistency across edges. Large platforms (Netflix Open Connect) place appliances inside ISPs so popular video never crosses the wider internet. Security: DDoS absorption, WAF, signed URLs/cookies for private media.'],
      check: mc('Why does Netflix put cache appliances inside ISPs?', ['Aesthetics', 'To serve popular video from within the user\'s own network, cutting cost and latency', 'To store passwords', 'To run SQL'], 1, 'Move bytes less far.') },
  ],
  diagram: { caption: 'CDN edge in front of origin', rows: [['Users worldwide'], ['CDN edge locations'], ['Origin server']], link: 'chain' },
  sections: { when: ['Static assets, media, downloads, global audiences, traffic spikes.'], whenNot: ['Highly dynamic private data (unless carefully keyed); tiny local-only apps.'], tradeoffs: ['Speed and offload vs cost, invalidation delay and cache-key complexity.'], real: ['Cloudflare, Akamai, CloudFront, Fastly; Netflix Open Connect.'] },
  connects: 'A CDN is caching moved to the network edge, and works because DNS can send each user to the nearest copy.',
  quiz: [
    mc('Which content is ideal for a CDN?', ['Bank balance JSON', 'Images and JS files', 'Passwords', 'DB writes'], 1, 'Static and shared.'),
    mc('What is an edge server?', ['A database', 'A CDN server near users', 'A DNS root', 'A cookie'], 1, 'Points of presence close to users.'),
    mc('Cache busting means…?', ['Deleting the CDN', 'Making new versions use new URLs', 'Encrypting', 'Slowing down'], 1, 'Hash in filename.'),
    mc('Users in Asia complain images are slow; servers are in Europe. First step?', ['Bigger DB', 'Serve static assets via CDN', 'Add indexes', 'Use UDP'], 1, 'Reduce distance.', 'scenario'),
    mc('After a deploy users get old CSS for hours. Likely cause and fix?', ['DNS; flush', 'Long-cached same-name file; use hashed filenames or purge', 'DB bug', 'Bad CPU'], 1, 'Version the asset URLs.', 'scenario'),
  ],
  interview: { q: 'How does a CDN work and when would you use one?', model: 'A CDN is a geographically distributed cache. Users are routed (DNS/anycast) to the nearest edge; on a hit the edge serves directly, on a miss it fetches from the origin, stores per Cache-Control, and serves. Use for static assets, media, downloads and global traffic; it lowers latency, offloads the origin and absorbs spikes. Handle updates with versioned URLs or purge, and avoid caching private per-user responses.', points: [pt('Distributed edge caches near users', 'edge', 'nearest', 'geograph'), pt('Hit/miss and origin fetch', 'origin', 'miss', 'hit'), pt('Cache-Control / TTL', 'cache-control', 'ttl', 'max-age'), pt('Versioned URLs / purge', 'version', 'hash', 'purge', 'invalidat'), pt('Don\'t cache private data', 'private', 'personal', 'per-user')] },
  challenge: { q: 'Design asset delivery for a news site with a global audience: images, article JSON, a personalised "for you" feed. State what is CDN-cached, for how long, and how updates propagate.', hints: ['Which items are the same for everyone?', 'What do you do for breaking-news edits?'], model: 'Images: long TTL with hashed names. Article JSON: short TTL (30-60 s) or stale-while-revalidate plus purge on edit for breaking news. "For you" feed: not publicly cached (private/no-store) or assembled client-side from cached parts. Origin shield reduces origin hits.', points: [pt('Long TTL + hashed names for images', 'hash', 'long', 'immutable'), pt('Short TTL or purge for articles', 'short', 'purge', 'stale'), pt('Personalised content not shared-cached', 'private', 'personal', 'no-store')] },
  summary: { key: ['CDN = caches near users.', 'Great for static content; versioned URLs.', 'Never publicly cache private data.'], mistakes: ['Same filename with long TTL.', 'Caching personalised responses.'], remember: 'Move bytes closer; do less work at the origin.' },
  refs: [ref('Cloudflare: What is a CDN?', 'https://www.cloudflare.com/learning/cdn/what-is-a-cdn/', 'Clear introduction to edge delivery.'), ref('MDN: HTTP caching', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching', 'The authoritative reference for Cache-Control.')],
},
{
  id: 'queues', title: 'Message queues, Kafka and background jobs', stage: 3, tier: 'must', minutes: 60, prereq: ['backend-servers', 'why-slow'], related: ['idempotency-retries', 'event-driven-obs'],
  hook: { story: 'A user clicks "Place order". Your server must charge the card, update inventory, send an email, notify the warehouse and update analytics. The email provider is slow today.', ask: 'Should the user wait for all of that before seeing "order placed"? What if the warehouse system is down for a minute?', hints: ['Which steps must finish before replying to the user?', 'Which can happen a moment later?', 'Where would you write down "to do later" so it is not forgotten?'], reveal: 'Do the essential work synchronously, then write the remaining tasks onto a durable **queue** and reply immediately. Separate **workers** process them in the background, retrying if they fail. The user is fast, and slow or broken downstream systems cannot break checkout.' },
  levels: [
    { title: 'Understand', body: ['A **message queue** is a to-do line between programs. A **producer** puts a message ("send welcome email to Asha") on the queue. A **consumer** (worker) takes it and does the job whenever it can.', 'It is like a restaurant order ticket rail: the waiter does not wait for the dish to be cooked; they pin the ticket and move on. Cooks pick tickets at their own pace.', 'Benefits: faster responses, smoothing traffic spikes (the queue absorbs the burst), resilience (work waits if a consumer is down), and decoupling.'],
      check: mc('What is a producer?', ['A database', 'The component that adds messages to the queue', 'A user', 'A cache'], 1, 'Producers publish, consumers consume.') },
    { title: 'Explore', body: ['Message lifecycle: producer sends → broker stores durably → consumer receives → consumer processes → consumer **acknowledges (ack)** → broker deletes it. If the consumer crashes before ack, the broker **redelivers** it. That gives **at-least-once** delivery: no loss, but possible duplicates, so consumers must be **idempotent**.'],
      steps: ['**RabbitMQ (traditional broker):** smart broker, queues and exchanges, per-message routing, ack/nack, good for task queues and complex routing; messages are removed once consumed.', '**Kafka (distributed log):** messages appended to a partitioned, replicated log and kept for days; consumers track their own **offset**; huge throughput, replay, ordering **within a partition**, consumer groups share partitions.', '**SQS / Redis streams / Celery** for simpler managed or lightweight needs.', '**Dead-letter queue:** messages that keep failing go aside for inspection instead of blocking everything.'],
      check: mc('A consumer processes a message but crashes before acknowledging. What happens?', ['Message lost', 'Broker redelivers it, so processing may happen twice', 'Queue deleted', 'DB rolls back'], 1, 'At-least-once delivery means duplicates are possible.') },
    { title: 'Apply', body: ['**Scenario: messages are getting lost / users get duplicate notifications.** Lost: producer sent without confirming the broker stored it, or consumer acked before processing. Fix: publisher confirms, durable queues, ack only after success. Duplicates: redelivery after a crash or retry. Fix: make the handler idempotent (store a processed-message id, or use a unique constraint on "notification for event X to user Y").', 'Also watch **queue depth**: if it keeps growing, consumers are too slow; add consumers (scale out) or fix the slow job. Use backpressure and alerts.'],
      check: mc('Users receive the same push notification twice after a consumer restart. Fix?', ['Drop the queue', 'Idempotent consumer using a dedupe key', 'Slower consumers', 'Bigger messages'], 1, 'At-least-once requires idempotent handling.') },
    { title: 'Master', body: ['Ordering: queues guarantee order only within a partition/queue; key messages (e.g. by user id) so related events land in the same partition. **Exactly-once** is mostly a marketing term for at-least-once + idempotent processing (Kafka offers transactional exactly-once within Kafka). Choose partitions up front: they cap consumer parallelism. Handle **poison messages**, retries with backoff, schema evolution, and **outbox pattern** (write the event to the same DB transaction as the change, then publish) to avoid "DB updated but message not sent". Kafka suits event streaming and replay; RabbitMQ/SQS suit job distribution; do not use a queue where a synchronous answer is needed.'],
      check: mc('How do you keep all events of one user in order in Kafka?', ['Impossible', 'Use the user id as the message key so they go to one partition', 'Use more brokers only', 'Use UDP'], 1, 'Ordering is per partition.') },
  ],
  diagram: { caption: 'Async processing', rows: [['Web server (producer)'], ['Queue / broker'], ['Worker 1', 'Worker 2', 'Worker 3']], link: 'fan' },
  sections: { when: ['Slow or unreliable downstream work, traffic spikes, fan-out to many consumers, decoupling teams, retries.'], whenNot: ['When the user needs the result immediately; simple in-process work; strict ordering across all messages.'], tradeoffs: ['Responsiveness and resilience vs eventual results, duplicates, extra infrastructure and harder debugging.'], real: ['LinkedIn built Kafka; Uber, Netflix and Airbnb use it for event streams; Shopify and GitHub use job queues for background work.'] },
  connects: 'Queues let you accept work faster than you can process it, flattening the spikes from the "why slow" lesson; at-least-once delivery is the reason idempotency (later) is essential.',
  quiz: [
    mc('Which delivery guarantee do most brokers give by default?', ['Exactly once, always', 'At-least-once', 'At-most-never', 'Random'], 1, 'Redelivery on failure means possible duplicates.'),
    mc('What does a dead-letter queue hold?', ['Spam', 'Messages that repeatedly fail processing', 'Encrypted data', 'User sessions'], 1, 'Keeps poison messages from blocking.'),
    mc('Kafka consumers track progress with…?', ['Cookies', 'Offsets', 'Locks', 'DNS'], 1, 'Each consumer group stores offsets per partition.'),
    mc('Queue depth grows steadily for an hour. What does it tell you?', ['All fine', 'Consumers are slower than producers; scale or fix the job', 'DNS issue', 'Cache full'], 1, 'Arrival rate exceeds processing rate.', 'scenario'),
    mc('Order saved in the DB but the "order created" event was never published because the app crashed in between. Pattern to fix?', ['More retries only', 'Transactional outbox', 'Bigger queue', 'UDP'], 1, 'Atomically record the event with the data change.', 'scenario'),
  ],
  interview: { q: 'When would you introduce a message queue, and how do you handle failures and duplicates?', model: 'Introduce a queue when work can be done asynchronously, downstream systems are slow or flaky, traffic is spiky, or multiple consumers need the event. The producer enqueues and returns; workers consume. Use durable queues, acks after processing, retries with backoff and a dead-letter queue. Delivery is usually at-least-once, so make consumers idempotent (dedupe keys). For ordering use per-key partitioning. Choose Kafka for high-throughput streaming/replay and RabbitMQ/SQS for job distribution. Use the outbox pattern to publish reliably.', points: [pt('Async work / spikes / decoupling', 'async', 'spike', 'decoupl'), pt('Ack, retry, dead-letter', 'ack', 'retry', 'dead'), pt('At-least-once and idempotent consumers', 'idempot', 'duplicate', 'at-least'), pt('Ordering via partitions/keys', 'partition', 'key', 'order'), pt('Kafka vs RabbitMQ choice / outbox', 'kafka', 'rabbit', 'outbox')] },
  challenge: { q: 'Design the email-sending path for sign-ups so that: the user sees success instantly, a provider outage loses no emails, and nobody gets two welcome emails.', hints: ['Where is the "to-do" stored durably?', 'What identifies one email uniquely?'], model: 'Sign-up transaction writes the user and an outbox row (or enqueues a message) with a unique id such as welcome:{user_id}. A worker reads and calls the provider; on failure it retries with backoff; after N failures it moves to a DLQ with an alert. The send step records the message id/uses the provider idempotency key to prevent duplicates.', points: [pt('Durable enqueue/outbox', 'outbox', 'queue', 'durable'), pt('Retries with backoff and DLQ', 'retry', 'backoff', 'dead', 'dlq'), pt('Unique id for dedupe / idempotent send', 'unique', 'idempot', 'dedupe', 'id')] },
  summary: { key: ['Queue decouples producers from consumers.', 'Ack after processing; at-least-once; make handlers idempotent.', 'Kafka = replayable log; RabbitMQ = routed tasks.'], mistakes: ['Ack before work completes.', 'Assuming exactly-once.'], remember: 'A growing queue means consumers are the bottleneck.' },
  refs: [ref('Apache Kafka: Introduction', 'https://kafka.apache.org/documentation/#introduction', 'Official explanation of topics, partitions and consumer groups.'), ref('RabbitMQ Tutorials', 'https://www.rabbitmq.com/tutorials', 'Hands-on official tutorials for work queues and routing.'), ref('microservices.io: Transactional outbox', 'https://microservices.io/patterns/data/transactional-outbox.html', 'Pattern for reliable event publishing.')],
},
{
  id: 'rate-limiting', title: 'Rate limiting and API gateways', stage: 3, tier: 'must', minutes: 45, prereq: ['http-rest', 'load-balancing'], related: ['idempotency-retries'],
  hook: { story: 'A single script starts hitting your login endpoint 5,000 times per second. Or a well-meaning customer\'s buggy loop calls your API non-stop.', ask: 'How do you protect the system and keep it fair to other users without blocking legitimate bursts?', hints: ['What should the server say to a client that is too fast?', 'Counting requests per user: where do you store the counts?', 'Is a short burst always bad?'], reveal: 'Add a **rate limiter**: count requests per client (user, API key, IP) and reject (HTTP 429) above a limit. Different algorithms decide how strictly to count and how bursts are treated.' },
  levels: [
    { title: 'Understand', body: ['A **rate limiter** is a bouncer: "10 requests per second per person". Beyond that, you wait. It protects servers from overload and abuse, keeps usage fair, and caps costs.', 'An **API gateway** is the single front door for all your APIs. It handles shared chores in one place: authentication, rate limiting, routing to the right service, logging, TLS.'],
      check: mc('Which HTTP status code means "too many requests"?', ['401', '404', '429', '503'], 2, '429 Too Many Requests, often with Retry-After.') },
    { title: 'Explore', body: ['Algorithms (try them live in the Rate Limiter lab):'],
      steps: ['**Token bucket:** a bucket holds up to N tokens, refilled at R per second; each request takes one. Allows bursts up to N, long-term rate R. Most popular.', '**Leaky bucket:** requests drain at a constant rate; smooths traffic, no bursts.', '**Fixed window counter:** count per minute; simple, but allows 2x bursts at window edges.', '**Sliding window log/counter:** accurate rolling count; more memory or an approximation.'],
      body2: ['Distributed storage of counters: Redis with atomic `INCR` + `EXPIRE` (or a Lua script) so all app servers share the same count. Limit by user id, API key, IP, or endpoint.'],
      check: mc('Which algorithm allows short bursts but enforces an average rate?', ['Fixed window', 'Token bucket', 'Random drop', 'DNS'], 1, 'Tokens accumulate up to the bucket size.') },
    { title: 'Apply', body: ['**Scenario: a distributed rate limiter across 20 app servers.** Per-server counters would let a client send 20x the limit. Use a shared Redis counter. But Redis then becomes a dependency: decide whether to **fail open** (allow when Redis is down: risk overload) or **fail closed** (block: risk outage). For login endpoints fail closed or use local fallback limits; for general APIs fail open is common.', 'Return helpful headers: `X-RateLimit-Remaining`, `Retry-After`, so well-behaved clients back off.'],
      check: mc('Counters kept in each server\'s memory with 20 servers means…?', ['Exact limit', 'Up to ~20x the intended limit', 'No limit needed', 'Zero traffic'], 1, 'State must be shared for a global limit.') },
    { title: 'Master', body: ['Edge cases: clock skew, race conditions on read-modify-write (use atomic scripts), hot keys, **burst vs sustained** policies, tiered plans (free vs paid), cost-aware limits (expensive endpoints cost more tokens), and **load shedding** (when the system itself is overloaded, drop low-priority traffic regardless of per-user limits). Rate limits at the gateway protect the whole system; per-service limits protect each service; clients need retry with jittered backoff to avoid synchronising.'],
      check: mc('Why can fixed-window counters be unfair?', ['They are random', 'A client can send a full quota at the end of one window and again at the start of the next', 'They use too much CPU', 'They ignore IPs'], 1, 'Edge bursts double the allowed rate.') },
  ],
  diagram: { caption: 'Gateway with limiter', rows: [['Clients'], ['API gateway (auth, rate limit)'], ['Service A', 'Service B']], link: 'fan' },
  sections: { when: ['Public APIs, login/OTP endpoints, expensive operations, multi-tenant systems.'], whenNot: ['Do not rely on client-side limiting for protection; do not set one global limit for very different endpoints.'], tradeoffs: ['Protection and fairness vs risk of blocking legitimate bursts and added dependency.'], real: ['Stripe, GitHub, Twitter/X all publish rate limits; Kong, Envoy, AWS API Gateway implement them.'] },
  connects: 'The limiter sits at the same place as the load balancer and uses a shared store like a cache, combining ideas from the previous lessons.',
  quiz: [
    mc('What does a token bucket do on a quiet client?', ['Nothing', 'Accumulates tokens up to its capacity, allowing a later burst', 'Blocks them', 'Deletes tokens'], 1, 'Unused capacity is saved up to the bucket size.'),
    mc('What is an API gateway responsible for?', ['Storing data', 'Central auth, routing, rate limiting, logging', 'Compiling code', 'DNS'], 1, 'Cross-cutting concerns at the front door.'),
    mc('Where should the limit counter live for 20 stateless servers?', ['Local memory', 'Shared Redis', 'Browser', 'Disk'], 1, 'Shared and atomic.'),
    mc('Redis for rate limits goes down. For a public read API you choose…?', ['Fail closed always', 'Often fail open with local fallback limits', 'Crash', 'Ban all'], 1, 'Availability vs protection trade-off.', 'scenario'),
    mc('A client retries immediately after every 429. What should the client do?', ['Retry faster', 'Back off using Retry-After / exponential backoff with jitter', 'Ignore', 'Use more IPs'], 1, 'Cooperative backoff prevents storms.', 'scenario'),
  ],
  interview: { q: 'Design a rate limiter for an API used by millions of clients.', model: 'Requirements: per-user/API-key limits, low latency, distributed, accurate enough. Use token bucket (burst + sustained rate) with counters in Redis updated atomically (Lua/INCR+EXPIRE), keyed by client and endpoint. Place the check at the API gateway/edge. Return 429 with Retry-After and rate-limit headers. Decide fail-open vs fail-closed on Redis outage; shard Redis by key; add local approximate counters to cut latency. Discuss fixed vs sliding window trade-offs, hot keys, clock skew and tiered limits.', points: [pt('Clarifies requirements (who, how many, where)', 'per user', 'api key', 'ip', 'requirement'), pt('Algorithm choice (token bucket / sliding window)', 'token bucket', 'sliding', 'leaky'), pt('Shared atomic store (Redis)', 'redis', 'atomic', 'lua'), pt('429 + headers + client backoff', '429', 'retry-after', 'backoff'), pt('Failure mode (fail open/closed) / scaling', 'fail open', 'fail closed', 'shard', 'hot key')] },
  challenge: { q: 'Limit login attempts: 5 per 15 minutes per account and 100 per hour per IP. Which algorithm and keys? What about an attacker using many IPs against one account?', hints: ['Two keys, two limits.', 'Which limit actually stops many-IP attacks?'], model: 'Sliding window (or fixed window with Redis INCR+EXPIRE) on key login:acct:{id} (5/15min) and login:ip:{ip} (100/h). The per-account limit stops the many-IP attack; add exponential lockout, CAPTCHA/MFA step-up, and alerts. Avoid revealing whether the account exists.', points: [pt('Two keys: account and IP', 'account', 'ip'), pt('Per-account stops distributed attack', 'many ip', 'distributed', 'per account', 'account limit'), pt('Lockout/backoff/MFA/CAPTCHA', 'lockout', 'backoff', 'mfa', 'captcha')] },
  summary: { key: ['Limit by key; reject with 429.', 'Token bucket allows bursts; fixed window has edge bursts.', 'Shared atomic counters for distributed limits.'], mistakes: ['Per-server counters.', 'No decision on fail-open vs fail-closed.'], remember: 'A limiter protects the system and keeps users fair.' },
  refs: [ref('Stripe: Rate limiters and load shedders', 'https://stripe.com/blog/rate-limiters', 'Real production rate limiting and load shedding design.'), ref('Cloudflare: What is rate limiting?', 'https://www.cloudflare.com/learning/bots/what-is-rate-limiting/', 'Plain overview of purposes and approaches.')],
},
{
  id: 'replication-sharding', title: 'Replication, read replicas and sharding', stage: 3, tier: 'must', minutes: 60, prereq: ['databases', 'scaling', 'caching'], related: ['cap-consistency', 'distributed-intro'],
  hook: { story: 'Your single database has everything, and it is at 95% CPU. Reads dominate (90%) but there are also lots of writes. Worse, if that one machine dies, the business stops.', ask: 'How can you (1) survive losing the machine, (2) serve more reads, (3) eventually store more data than one machine can hold? Are these the same problem?', hints: ['Keeping an extra copy helps survive failure and serve reads.', 'Does copying help with writes or data size?', 'To hold more data, you must split it. By what rule?'], reveal: 'They are different problems with different tools. **Replication** (copies) gives availability and read scaling. **Sharding** (splitting) gives write and storage scaling. Each brings its own consistency and complexity costs.' },
  levels: [
    { title: 'Understand', body: ['**Replication:** keep copies of the database on several machines. One is the **primary** (accepts writes); the others are **replicas** that copy its changes and serve reads. If the primary fails, a replica takes over.', '**Sharding:** split the data across machines so each holds only a part, e.g. users A-M on shard 1, N-Z on shard 2. Like splitting a library into branches by author surname.', 'Rule of thumb: replicate first (easier), shard only when one machine cannot take your writes or data.'],
      check: mc('Which technique helps you store more data than one machine can hold?', ['Replication', 'Sharding', 'Caching', 'Indexing'], 1, 'Replicas each hold everything; shards hold parts.') },
    { title: 'Explore', body: ['**Replication lag:** the primary acknowledges a write, and replicas apply it a few ms to seconds later (**asynchronous**). A read from a replica may be stale. **Synchronous** replication waits for replicas before acknowledging: safer, slower. Many systems use semi-sync (wait for one).', '**Failover:** detect primary failure, promote the most up-to-date replica, redirect clients. Risks: losing the last un-replicated writes, and **split brain** (two nodes both think they are primary).'],
      steps: ['**Shard key** decides placement. Good keys spread load evenly and keep related data together (user_id).', '**Hash sharding:** shard = hash(key) mod N. Even spread, but adding a shard remaps almost everything. **Consistent hashing** moves only ~1/N of keys.', '**Range sharding:** contiguous ranges (A-M); good for range scans, risks **hot spots** (all new IDs hit the last shard).', '**Directory/lookup sharding:** a map says where each key lives; flexible, but the map is a dependency.', 'Cross-shard queries and joins become hard; cross-shard transactions need 2PC or sagas.'],
      check: mc('Why is "hash(key) mod N" painful when you add a shard?', ['It is slower', 'Nearly all keys map to a different shard, forcing mass data movement', 'It breaks encryption', 'Replicas vanish'], 1, 'Consistent hashing fixes this (see Sharding lab).') },
    { title: 'Apply', body: ['**Scenario: a user posts a comment and refreshes, but the comment is missing.** The write went to the primary; the refresh was read from a lagging replica. Fixes: read-your-own-writes (route a user\'s reads to the primary for a few seconds after they write, or track the write\'s position), or accept and design the UI for it.', '**Scenario: choose a shard key for a chat app.** `conversation_id` keeps one chat\'s messages together (fast history, ordered), but a huge group chat becomes a hot shard. `user_id` spreads users but scatters a conversation across shards. State the trade-off and justify against the access pattern.'],
      check: mc('Commenter does not see their comment after refresh (replica lag). Best targeted fix?', ['Remove replicas', 'Read-your-own-writes: read from primary briefly after writes', 'Shorter TTL', 'More shards'], 1, 'Give the writer a consistent view without hurting everyone.') },
    { title: 'Master', body: ['**Resharding** is the real cost: pre-split into many small logical shards (e.g. 1,024) mapped onto fewer machines so you can move whole logical shards later. **Hot shards** need splitting or key salting. Multi-leader and leaderless (Dynamo-style) replication increase availability but need conflict resolution (last-write-wins, vector clocks, CRDTs). Quorum reads/writes (R + W > N) give tunable consistency. Instagram and Discord have written about their sharding schemes (ID generation embedding the shard id, partitioning by channel and time bucket).', 'Interview framing: "I would first use read replicas and caching; if write throughput or data size still exceeds a node, shard by X because the dominant access pattern is Y; cross-shard operations are Z."'],
      check: mc('Why pre-split into many logical shards?', ['Looks nicer', 'Rebalancing later means moving whole logical shards rather than rehashing every key', 'Encryption', 'Cheaper DNS'], 1, 'Cheap, incremental scaling.') },
  ],
  diagram: { caption: 'Primary + replicas, and shards', rows: [['App'], ['Primary (writes)'], ['Replica 1', 'Replica 2'], ['Shard A', 'Shard B', 'Shard C']], link: 'chain' },
  sections: { when: ['Replicas: read-heavy workloads, high availability. Shards: write/storage beyond one node.'], whenNot: ['Do not shard early; do not read critical, must-be-fresh data from lagging replicas.'], tradeoffs: ['Scale and availability vs consistency, operational and query complexity.'], real: ['Instagram: sharded PostgreSQL with embedded shard IDs; Discord: messages partitioned by channel; Vitess shards MySQL for YouTube.'] },
  connects: 'Replication and sharding make data distributed, which immediately raises the CAP and consistency questions of the next stage.',
  quiz: [
    mc('What is replication lag?', ['Slow DNS', 'Delay before a replica reflects a primary write', 'Disk full', 'Cache TTL'], 1, 'Async replicas trail the primary.'),
    mc('What is a shard key?', ['A password', 'The attribute that decides which shard stores a row', 'An index type', 'A cache key'], 1, 'Placement rule.'),
    mc('Which is a hot-spot risk?', ['Hash sharding with good spread', 'Range sharding on an auto-increment ID', 'Replicas', 'CDN'], 1, 'All new writes hit the newest range.'),
    mc('Your app is 95% reads and the primary is saturated. First move?', ['Shard immediately', 'Add read replicas and caching', 'Rewrite in Go', 'Double the TTL on DNS'], 1, 'Cheapest scaling for reads.', 'scenario'),
    mc('The primary fails and a lagging replica is promoted. What risk?', ['None', 'Recent acknowledged writes may be lost', 'Faster reads', 'More replicas'], 1, 'Async replication trades durability for speed.', 'scenario'),
  ],
  interview: { q: 'Your database is overloaded. Walk me through replication vs sharding and how you would choose a shard key.', model: 'Diagnose first. Reads: add caching and read replicas (async, lag, route consistency-sensitive reads to primary). Availability: replicas plus automated failover (beware split brain and lost writes). Writes/storage beyond one node: shard. Pick a key from the dominant access pattern with high cardinality and even distribution (e.g. user_id), avoiding hot spots; use consistent hashing or pre-split logical shards for resharding. Costs: cross-shard queries/transactions, rebalancing, operational complexity.', points: [pt('Replication for read scale and failover', 'replica', 'failover'), pt('Replication lag / consistency trade-off', 'lag', 'stale', 'consisten'), pt('Sharding for write/storage', 'shard', 'partition'), pt('Shard key criteria (access pattern, even spread)', 'key', 'cardinal', 'even', 'hot'), pt('Costs: cross-shard queries, resharding', 'cross-shard', 'reshard', 'rebalanc', 'join')] },
  challenge: { q: 'Choose the shard key and layout for a photo-sharing app\'s "photos" table (billions of rows). Queries: photos of one user (most common), a single photo by id, trending photos globally. Justify and describe the awkward query.', hints: ['Which query is most common?', 'How do you find a photo by id alone?'], model: 'Shard by user_id (most common query hits one shard). Embed the shard id in photo ids (Instagram style) so lookups by photo id route directly. Trending is a cross-shard aggregation: precompute it offline into a separate store/cache. Celebrity users create hot shards: split or cache them.', points: [pt('Shards by user_id for dominant query', 'user_id', 'user'), pt('Routes photo-id lookups (id embeds shard/lookup)', 'embed', 'lookup', 'id encodes', 'shard id'), pt('Handles cross-shard trending separately', 'precompute', 'aggregate', 'separate', 'offline'), pt('Mentions hot users/shards', 'hot', 'celebrity')] },
  summary: { key: ['Replication = copies (reads, availability). Sharding = splits (writes, size).', 'Replication lag causes stale reads.', 'Shard key follows the access pattern.'], mistakes: ['Sharding too early.', 'Reading must-be-fresh data from replicas.'], remember: 'Every distribution technique trades consistency or simplicity for scale.' },
  refs: [ref('Sharding & IDs at Instagram (post excerpt, original blog is offline)', 'https://thebuild.com/blog/sharding-ids-at-instagram/', 'Real sharding scheme with embedded shard ids.'), ref('Discord: How Discord Stores Billions of Messages', 'https://discord.com/blog/how-discord-stores-billions-of-messages', 'Partitioning and database migration case study.'), ref('PostgreSQL docs: High availability and replication', 'https://www.postgresql.org/docs/current/high-availability.html', 'Official replication concepts.')],
},
]
